package com.example.blades360;

import android.app.Activity;
import android.content.*;
import android.graphics.BitmapFactory;
import android.net.Uri;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Portable metadata and cover backup, excluding ROMs, music and captures. */
final class SetupBackup {
  static final int EXPORT=3801,IMPORT=3802;
  final Activity activity;final EmulatorLibrary library;final ExecutorService worker=Executors.newSingleThreadExecutor();
  boolean busy,closed;String status="";Runnable changed;
  SetupBackup(Activity a,EmulatorLibrary l){activity=a;library=l;}
  void update(String message){status=message;if(changed!=null)changed.run();}
  void exportSetup(){if(busy)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"Blades360-setup.zip");try{activity.startActivityForResult(i,EXPORT);}catch(Exception e){update("No document picker is available.");}}
  void importSetup(){if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);try{activity.startActivityForResult(i,IMPORT);}catch(Exception e){update("No document picker is available.");}}
  boolean result(int request,int result,Intent data){if(request!=EXPORT&&request!=IMPORT)return false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){update("Backup operation cancelled.");return true;}if(busy)return true;Uri uri=data.getData();busy=true;library.save();Map<String,?> snapshot=new HashMap<>(library.prefs.getAll());update(request==EXPORT?"Exporting settings and covers...":"Validating and merging backup...");worker.execute(()->{try{if(request==EXPORT){String report=write(uri,snapshot);finish(report);}else read(uri);}catch(Exception e){finish("Backup failed: "+(e.getMessage()==null?"file unavailable":e.getMessage()));}});return true;}
  void finish(String message){activity.runOnUiThread(()->{busy=false;if(!closed)update(message);});}
  JSONObject settings(Map<String,?> snapshot)throws Exception{JSONObject settings=new JSONObject();for(Map.Entry<String,?> e:snapshot.entrySet()){if(e.getKey().equals("games"))continue;Object v=e.getValue();JSONObject typed=new JSONObject();if(v instanceof Boolean)typed.put("type","boolean").put("value",v);else if(v instanceof Integer)typed.put("type","int").put("value",v);else if(v instanceof Long)typed.put("type","long").put("value",v);else if(v instanceof Float)typed.put("type","float").put("value",v);else if(v instanceof String)typed.put("type","string").put("value",v);else if(v instanceof Set)typed.put("type","set").put("value",new JSONArray((Set<?>)v));else continue;settings.put(e.getKey(),typed);}return settings;}
  String write(Uri destination,Map<String,?> snapshot)throws Exception{
    JSONArray games=new JSONArray(String.valueOf(snapshot.containsKey("games")?snapshot.get("games"):"[]"));if(games.length()>10000)throw new IOException("Too many library entries");JSONObject manifest=new JSONObject().put("format","Blades360Setup").put("version",1).put("created",System.currentTimeMillis()).put("settings",settings(snapshot)).put("games",games);
    File temporary=new File(activity.getCacheDir(),"setup-export-"+UUID.randomUUID()+".zip");HashMap<String,String> reused=new HashMap<>();Set<String> assets=new HashSet<>();int missing=0;long total=0;
    try{try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(temporary))){for(int i=0;i<games.length();i++){JSONObject game=games.getJSONObject(i);String art=game.optString("artUri");if(art.isEmpty())continue;if(reused.containsKey(art)){game.put("artAsset",reused.get(art));continue;}try(InputStream in=activity.getContentResolver().openInputStream(Uri.parse(art))){if(in==null)throw new IOException();byte[] bytes=BackupArchive.bounded(in,BackupArchive.MAX_ENTRY);validateImage(bytes);String name="artwork/"+BackupArchive.hash(bytes)+".img";if(!assets.contains(name)){if(total+bytes.length>BackupArchive.MAX_TOTAL-BackupArchive.MAX_ENTRY||assets.size()>=5000){missing++;continue;}zip.putNextEntry(new ZipEntry(name));zip.write(bytes);zip.closeEntry();assets.add(name);total+=bytes.length;}reused.put(art,name);game.put("artAsset",name);}catch(Exception e){missing++;}}byte[] json=manifest.toString().getBytes(StandardCharsets.UTF_8);if(json.length>BackupArchive.MAX_ENTRY)throw new IOException("Setup metadata too large");zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(json);zip.closeEntry();}
      try(InputStream in=new FileInputStream(temporary);OutputStream out=activity.getContentResolver().openOutputStream(destination,"wt")){if(out==null)throw new IOException("Cannot write selected file");byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
      return "Exported "+games.length()+" entries and "+assets.size()+" covers."+(missing>0?" "+missing+" unavailable/oversized covers skipped.":"")+" ROMs and music are not included.";
    }finally{temporary.delete();}
  }
  void validateImage(byte[] bytes)throws IOException{BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,opt);if(opt.outWidth<=0||opt.outHeight<=0||opt.outWidth>8192||opt.outHeight>8192)throw new IOException("Invalid or oversized cover image");}
  void validateKnown(String key,JSONObject typed)throws Exception{
    String type=typed.getString("type"),expected="";
    if(Arrays.asList("sound_enabled","confirm_launch","auto_art","music_shuffle").contains(key))expected="boolean";
    if(Arrays.asList("sound_volume","deadzone","music_repeat").contains(key))expected="int";
    if(Arrays.asList("music_tree","music_playlists","loaded_game_uri","library_sort").contains(key)||key.startsWith("default_emulator_"))expected="string";
    if(key.startsWith("emulation_audio_")||key.startsWith("emulation_rewind_"))expected="boolean";
    if(key.startsWith("emulation_display_")||key.startsWith("emulation_filter_")||key.startsWith("emulation_variable_"))expected="string";
    if(key.startsWith("touch_layout_"))expected="string";
    if(key.startsWith("emulation_display_")&&!Arrays.asList("true","full","wide","4:3").contains(typed.getString("value")))throw new IOException("Invalid game display mode");
    if(key.startsWith("emulation_filter_")&&!Arrays.asList("sharp","default","crt","lcd").contains(typed.getString("value")))throw new IOException("Invalid game video filter");
    if(key.startsWith("emulation_variable_")&&typed.getString("value").length()>256)throw new IOException("Core setting too long");
    if(key.startsWith("touch_layout_")){
      String raw=typed.getString("value");if(raw.length()>65536)throw new IOException("Controller layout too large");
      JSONObject config=new JSONObject(raw);JSONArray layouts=config.getJSONArray("layouts");if(layouts.length()<1||layouts.length()>12)throw new IOException("Invalid controller layout count");
      for(int i=0;i<layouts.length();i++){JSONObject layout=layouts.getJSONObject(i);if(layout.optString("name").length()>36)throw new IOException("Controller layout name too long");double opacity=layout.getDouble("opacity");if(!Double.isFinite(opacity)||opacity<.14999||opacity>.85001)throw new IOException("Invalid controller opacity");JSONArray nodes=layout.getJSONArray("controls");if(nodes.length()>32)throw new IOException("Too many controls");for(int n=0;n<nodes.length();n++){JSONObject node=nodes.getJSONObject(n);for(String field:Arrays.asList("x","y","size")){double value=node.getDouble(field);if(!Double.isFinite(value)||value<0||value>2)throw new IOException("Invalid controller position");}}}
    }
    if(!expected.isEmpty()&&!type.equals(expected))throw new IOException("Wrong type for "+key);
    if(key.equals("sound_volume")&&(typed.getInt("value")<0||typed.getInt("value")>100))throw new IOException("Invalid sound volume");
    if(key.equals("deadzone")&&(typed.getInt("value")<0||typed.getInt("value")>90))throw new IOException("Invalid stick dead zone");
    if(key.equals("music_repeat")&&(typed.getInt("value")<0||typed.getInt("value")>2))throw new IOException("Invalid repeat setting");
    if(key.equals("library_sort")&&!Arrays.asList("Title","Recently played","Console").contains(typed.getString("value")))throw new IOException("Invalid library sort");
    if(key.startsWith("default_emulator_")&&!typed.getString("value").matches("[A-Za-z0-9_.]*"))throw new IOException("Invalid default emulator");
    if(key.equals("music_tree")){String uri=typed.getString("value");if(!uri.isEmpty()&&(!uri.startsWith("content://")||!android.provider.DocumentsContract.isTreeUri(Uri.parse(uri))))throw new IOException("Invalid music folder");}
    if(key.equals("music_playlists")){JSONObject lists=new JSONObject(typed.getString("value"));if(lists.length()>500)throw new IOException("Too many playlists");Iterator<String> names=lists.keys();while(names.hasNext()){String name=names.next();if(name.length()>256)throw new IOException("Playlist name too long");JSONArray tracks=lists.getJSONArray(name);if(tracks.length()>10000)throw new IOException("Playlist too large");for(int i=0;i<tracks.length();i++){String uri=tracks.getString(i);if(uri.length()>16384||!(uri.startsWith("content://")||uri.startsWith("file://")))throw new IOException("Invalid playlist track");}}}
  }
  String mergePlaylists(String old,String imported)throws Exception{JSONObject current=new JSONObject(old),incoming=new JSONObject(imported);Iterator<String> names=incoming.keys();while(names.hasNext()){String name=names.next();JSONArray source=incoming.getJSONArray(name),target=current.optJSONArray(name);if(target==null){current.put(name,source);continue;}HashSet<String> seen=new HashSet<>();for(int i=0;i<target.length();i++)seen.add(target.getString(i));for(int i=0;i<source.length();i++)if(seen.add(source.getString(i)))target.put(source.getString(i));}return current.toString();}
  void read(Uri source)throws Exception{
    File stage=new File(activity.getCacheDir(),"setup-import-"+UUID.randomUUID());if(!stage.mkdirs())throw new IOException("Cannot stage backup");Map<String,File> assets=new HashMap<>();final JSONObject[] manifest={null};
    try{InputStream stream=activity.getContentResolver().openInputStream(source);if(stream==null)throw new IOException("Cannot read backup");BackupArchive.read(stream,(name,bytes)->{if(name.equals("manifest.json")){manifest[0]=new JSONObject(new String(bytes,StandardCharsets.UTF_8));}else{validateImage(bytes);File f=new File(stage,name.substring(8));try(FileOutputStream out=new FileOutputStream(f)){out.write(bytes);}assets.put(name,f);}});
      JSONObject m=manifest[0];if(m==null||!m.optString("format").equals("Blades360Setup")||m.optInt("version")!=1)throw new IOException("Unsupported backup format");JSONArray incoming=m.getJSONArray("games");if(incoming.length()>10000)throw new IOException("Too many library entries");JSONObject importedSettings=m.getJSONObject("settings");validateSettings(importedSettings);
      for(int i=0;i<incoming.length();i++){JSONObject g=incoming.getJSONObject(i);String uri=g.getString("uri"),name=g.getString("name");if(uri.length()>16384||name.length()>2048||!(uri.startsWith("content://")||uri.startsWith("file://")))throw new IOException("Invalid game entry");String art=g.optString("artAsset");if(!art.isEmpty()&&!assets.containsKey(art))throw new IOException("A referenced cover is missing");String pkg=g.optString("emulator");if(!pkg.isEmpty()&&!pkg.matches("[A-Za-z0-9_.]+"))throw new IOException("Invalid emulator assignment");}
      // All validation completes before persistent settings or cover files change.
      File coverDir=new File(activity.getFilesDir(),"boxart");coverDir.mkdirs();for(int i=0;i<incoming.length();i++){JSONObject g=incoming.getJSONObject(i);String art=g.optString("artAsset");if(!art.isEmpty()){File target=new File(coverDir,"backup-"+art.substring(8));File f=assets.get(art);if(!target.exists()){File temp=new File(coverDir,target.getName()+".tmp");try(InputStream in=new FileInputStream(f);OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}if(!temp.renameTo(target)){temp.delete();throw new IOException("Cannot store imported cover");}}g.put("artUri",Uri.fromFile(target).toString());}else g.put("artUri","");g.remove("artAsset");}
      activity.runOnUiThread(()->{if(closed){busy=false;return;}try{merge(incoming,importedSettings);}catch(Exception e){busy=false;update("Backup merge failed: "+e.getMessage());}});
    }finally{File[] files=stage.listFiles();if(files!=null)for(File f:files)f.delete();stage.delete();}
  }
  void validateSettings(JSONObject settings)throws Exception{if(settings.length()>1000)throw new IOException("Too many settings");Iterator<String> keys=settings.keys();while(keys.hasNext()){String key=keys.next();if(key.length()>256||key.equals("games"))throw new IOException("Invalid setting key");JSONObject value=settings.getJSONObject(key);validateKnown(key,value);String type=value.getString("type");if(!Arrays.asList("boolean","int","long","float","string","set").contains(type))throw new IOException("Invalid setting type");Object v=value.get("value");if(type.equals("string")&&!(v instanceof String)||type.equals("boolean")&&!(v instanceof Boolean))throw new IOException("Invalid setting value");if(type.equals("set")){JSONArray set=value.getJSONArray("value");if(set.length()>10000)throw new IOException("Setting set too large");for(int i=0;i<set.length();i++)set.getString(i);}else if(type.equals("int")||type.equals("long")||type.equals("float")){if(!(v instanceof Number))throw new IOException("Invalid number setting");}}}
  void merge(JSONArray incoming,JSONObject settings)throws Exception{
    library.save();JSONArray existing=new JSONArray(library.prefs.getString("games","[]"));HashMap<String,JSONObject> byUri=new HashMap<>();HashMap<String,ArrayList<JSONObject>> byTitle=new HashMap<>();for(int i=0;i<existing.length();i++){JSONObject g=existing.getJSONObject(i);byUri.put(g.getString("uri"),g);byTitle.computeIfAbsent(gameKey(g),k->new ArrayList<>()).add(g);}int added=0,merged=0;
    for(int i=0;i<incoming.length();i++){JSONObject g=incoming.getJSONObject(i),current=byUri.get(g.getString("uri"));if(current==null){ArrayList<JSONObject> same=byTitle.get(gameKey(g));if(same!=null&&same.size()==1)current=same.get(0);}if(current==null){existing.put(g);byUri.put(g.getString("uri"),g);added++;}else{current.put("favorite",current.optBoolean("favorite")||g.optBoolean("favorite"));current.put("played",Math.max(current.optLong("played"),g.optLong("played")));if(current.optString("emulator").isEmpty())current.put("emulator",g.optString("emulator"));if(current.optString("artUri").isEmpty())current.put("artUri",g.optString("artUri"));merged++;}}
    SharedPreferences.Editor edit=library.prefs.edit();Iterator<String> keys=settings.keys();while(keys.hasNext()){String key=keys.next();if(key.equals("music_playlists")&&library.prefs.contains(key)){edit.putString(key,mergePlaylists(library.prefs.getString(key,"{}"),settings.getJSONObject(key).getString("value")));continue;}if(library.prefs.contains(key))continue;JSONObject v=settings.getJSONObject(key);switch(v.getString("type")){case "string":edit.putString(key,v.getString("value"));break;case "boolean":edit.putBoolean(key,v.getBoolean("value"));break;case "int":edit.putInt(key,v.getInt("value"));break;case "long":edit.putLong(key,v.getLong("value"));break;case "float":edit.putFloat(key,(float)v.getDouble("value"));break;case "set":JSONArray arr=v.getJSONArray("value");Set<String> set=new HashSet<>();for(int i=0;i<arr.length();i++)set.add(arr.getString(i));edit.putStringSet(key,set);break;}}
    edit.putString("games",existing.toString());if(!edit.commit())throw new IOException("Could not save restored setup");library.games.clear();library.load();library.reloadSettings();library.artCache.evictAll();library.artFailed.clear();busy=false;update("Imported "+added+" entries; merged "+merged+". Existing settings and choices kept; playlists combined. On another device, reselect ROM/music folders to grant access.");
  }
  String gameKey(JSONObject g)throws Exception{return EmulatorLibrary.detectSystem(g.getString("uri"),g.getString("name"))+"/"+g.getString("name").toLowerCase(Locale.ROOT);}
  void close(){closed=true;worker.shutdown();}
}
